{
  "id": 3,
  "knowledge": "Scan Quality Score (SQS)",
  "description": "Comprehensive quality metric combining resolution, coverage, and noise factors with weighted importance.",
  "definition": "SQS = \\left(\\frac{10}{\\text{SRI}}\\right)^{1.5} \\times \\left(\\frac{\\text{SCE}}{100}\\right) \\times \\left(1 - \\frac{\\text{Noise Level (dB)}}{30}\\right)^2, \\text{ where higher values indicate exponentially better overall scan quality with emphasis on resolution.}"
}

{
  "id": 4,
  "knowledge": "Mesh Complexity Ratio (MCR)",
  "description": "Measures the topological complexity of a mesh relative to its resolution, helping identify overly complex or simplified archaeological models.",
  "definition": "MCR = \\frac{\\text{Mesh Faces}}{\\text{Mesh Vertices} \\times \\text{Mesh Resolution (mm)}^2} \\times 10^3, \\text{ where higher values indicate more complex meshes for a given resolution, capturing finer archaeological details.}"
}

{
  "id": 5,
  "knowledge": "Texture Density Index (TDI)",
  "description": "Evaluates the pixel density of textures relative to mesh resolution for assessing surface detail preservation.",
  "definition": "TDI = \\frac{\\text{Texture Size (px)}}{\\sqrt{\\text{Mesh Faces}} \\times \\text{Mesh Resolution (mm)}} \\times 10^{-2}, \\text{ where higher values indicate more detailed textures relative to geometric complexity.}"
}

{
  "id": 0,
  "knowledge": "Scan Resolution Index (SRI)",
  "description": "A sophisticated compound index measuring the overall resolution quality of a scan based on resolution and point density.",
  "definition": "SRI = \\frac{\\log_{10}(\\text{Scan Resolution (mm)} \\times 10^3)}{\\log_{10}(\\text{Point Density (points/m\u00b2)})} \\times 5, \\text{ where lower values indicate higher quality resolution and more balanced scanning parameters.}"
}

{
  "id": 2,
  "knowledge": "Point Cloud Density Ratio (PCDR)",
  "description": "Evaluates the relationship between total points and cloud density, used to assess scan efficiency and data distribution.",
  "definition": "PCDR = \\frac{\\text{Total Points}}{\\text{Point-Cloud Density Code} \\times \\text{Surface Area (m\u00b2)}}, \\text{ where higher values suggest more efficient and spatially consistent scanning techniques.}"
}
